package com.fstojilj.luddite.sync.server.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.jdbc.repository.config.AbstractJdbcConfiguration;
import org.springframework.data.relational.core.dialect.AnsiDialect;
import org.springframework.data.relational.core.dialect.Dialect;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcOperations;

@Configuration
public class JdbcConfig extends AbstractJdbcConfiguration {

    @Bean
    @Override
    public Dialect jdbcDialect(NamedParameterJdbcOperations operations) {
        return AnsiDialect.INSTANCE;
    }
}

package com.fstojilj.luddite.sync.server.service;

import com.fstojilj.luddite.sync.server.event.FileChangeEvent;
import lombok.extern.slf4j.Slf4j;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.locks.ReentrantLock;

@Slf4j
public class FileChangeEventBuffer {

    private final LinkedBlockingQueue<FileChangeEvent> queue = new LinkedBlockingQueue<>();
    private final ReentrantLock drainLock = new ReentrantLock();

    private FileChangeEventBuffer() {
    }

    private static class Holder {
        private static final FileChangeEventBuffer INSTANCE = new FileChangeEventBuffer();
    }

    public static FileChangeEventBuffer getInstance() {
        return Holder.INSTANCE;
    }

    public void publish(FileChangeEvent event) {
        if (!queue.offer(event)) {
            log.warn("FileChangeEvent queue is full, dropping event: {}", event);
        }
    }

    public List<FileChangeEvent> drain() {
        drainLock.lock();
        try {
            List<FileChangeEvent> events = new ArrayList<>();
            queue.drainTo(events);
            return events;
        } finally {
            drainLock.unlock();
        }
    }
}
